33	fn read_expected_errors() -> BTreeMap<String, bool> {
34	    let path = fixture_root().join("expected-errors.txt");
35	    let content = fs::read_to_string(&path)
36	        .unwrap_or_else(|err| panic!("failed to read {}: {err}", path.display()));
37	
38	    let mut map = BTreeMap::new();
39	
40	    for (idx, raw_line) in content.lines().enumerate() {
41	        let line = raw_line.trim();
42	        if line.is_empty() {
43	            continue;
44	        }
45	
46	        let (rel, value) = line.split_once('\t').unwrap_or_else(|| {
47	            panic!(
48	                "invalid expected-errors line {} in {}: {}",
49	                idx + 1,
50	                path.display(),
51	                line
52	            )
53	        });
54	
55	        let expected = match value {
56	            "true" => true,
57	            "false" => false,
58	            _ => {
59	                panic!(
60	                    "invalid expected-errors boolean on line {} in {}: {}",
61	                    idx + 1,
62	                    path.display(),
63	                    value
64	                )
65	            }
66	        };
67	
68	        let prev = map.insert(rel.to_string(), expected);
69	        assert!(
70	            prev.is_none(),
71	            "duplicate expected-errors entry in {}: {}",
72	            path.display(),
73	            rel
74	        );
75	    }
76	
77	    map
78	}
