66	fn with_parser<F, Ret>(
67	    treat_error_as_bug: bool,
68	    file_name: &Path,
69	    config_path: &Path,
70	    f: F,
71	) -> Result<Ret, StdErr>
72	where
73	    F: FnOnce(&mut Parser<Lexer>, &SingleThreadedComments) -> PResult<Ret>,
74	{
75	    ::testing::run_test(treat_error_as_bug, |cm, handler| {
76	        let comments = SingleThreadedComments::default();
77	
78	        let fm = cm
79	            .load_file(file_name)
80	            .unwrap_or_else(|e| panic!("failed to load {}: {}", file_name.display(), e));
81	
82	        let is_jsx = file_name
83	            .extension()
84	            .map(|ext| ext == "jsx")
85	            .unwrap_or_default();
86	
87	        let syntax = {
88	            let mut config_str = String::new();
89	            File::open(config_path)
90	                .ok()
91	                .and_then(|mut file| file.read_to_string(&mut config_str).ok())
92	                .and_then(|_| serde_json::from_str::<FlowSyntax>(&config_str).ok())
93	        }
94	        .map(|mut flow| {
95	            flow.jsx |= is_jsx;
96	            flow
97	        })
98	        .unwrap_or_else(|| FlowSyntax {
99	            jsx: is_jsx,
100	            ..Default::default()
101	        });
102	
103	        let lexer = Lexer::new(
104	            Syntax::Flow(syntax),
105	            EsVersion::Es2015,
106	            (&*fm).into(),
107	            Some(&comments),
108	        );
109	
110	        let mut p = Parser::new_from(lexer);
111	
112	        let res = f(&mut p, &comments).map_err(|e| e.into_diagnostic(handler).emit());
113	
114	        for err in p.take_errors() {
115	            err.into_diagnostic(handler).emit();
116	        }
117	
118	        if handler.has_errors() {
119	            return Err(());
120	        }
121	
122	        res
123	    })
124	}
